export default function input({ body }) {
  const name = String(body.folderName || "").trim(),
    parent = String(body.parentId || "").trim();
  if (!name || !parent || name.length > 200 || /[\r\n]/.test(name))
    throw Error("Expected parent and folder name");
  const esc = (x) => x.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
  return {
    name,
    parent,
    parents: [parent],
    query:
      "mimeType = 'application/vnd.google-apps.folder' and trashed = false and name = '" +
      esc(name) +
      "' and '" +
      esc(parent) +
      "' in parents",
  };
}

