export default async function plan({ name, parent, files, nextPageToken, resolution }, ctx) {
  if (nextPageToken || files.length > 1) throw Error("Multiple matching folders; resolve manually");
  const key = "drive-folder:" + parent + ":" + name,
    old = await ctx.state.get(key);
  if (old?.status === "pending") {
    if (!["applied", "absent"].includes(resolution)) throw Error("Inspect unknown folder creation");
    if (resolution === "applied") {
      if (files.length !== 1 || !files[0].id) throw Error("Expected exactly one created folder");
      await ctx.state.set(key, { status: "confirmed" });
      return { create: false, key, folderId: files[0].id };
    }
    if (files.length) throw Error("Folder exists; choose applied after verification");
  }
  if (files.length === 1) {
    if (!files[0].id) throw Error("Folder ID missing");
    return { create: false, key, folderId: files[0].id };
  }
  await ctx.state.set(key, { status: "pending" });
  return { create: true, key, folderId: "" };
}

